SELECT 'датчик шапки контракта ' || fact_gap($1, 'contract-head') || ': сходятся ли числа — неизвестно' AS detail WHERE NOT fact_fresh($1, 'contract-head') UNION ALL SELECT f.name || '  —  ' || f.detail FROM code_fact f WHERE f.project_id = $1 AND f.kind = 'contract-head' AND f.name NOT LIKE 'шапка · всего требований%' AND f.name NOT LIKE 'шапка · имя величины%' AND f.name NOT LIKE 'шапка · равенство%' AND f.name NOT LIKE 'шапка · тройка%' AND f.name NOT LIKE 'шапка · пара раскрывателя%' ORDER BY 1
